#!/bin/sh
# Autogenerated test: runs inside a container built from each compatibility image with rclone installed with default
# options (version latest, installMountDependencies false), as the image's remote user. POSIX sh, because alpine:3.24
# ships no bash.
set -eu

# The path is computed from $0 at run time, so shellcheck cannot follow it.
# shellcheck source=/dev/null
. "$(dirname "$0")/checks.sh"

# Before rclone runs at all: a plain rclone run creates ~/.config/rclone, so it cannot pass as written by the install.
check "neither the remote user's nor root's home holds .config/rclone, .cache/rclone, .rclone.conf, or .gnupg" \
  no_rclone_files_in_homes
check "no environment variable starting with RCLONE_ is set" no_rclone_variables

# Computed at run time: the default option installs whatever release the version file names.
latest="$(latest_release)"

check "command -v rclone resolves to /usr/local/bin/rclone" rclone_resolves_to_usr_local_bin
check "/usr/local/bin/rclone is executable by every user" test -x /usr/local/bin/rclone
check "rclone version reports the release the version file names" rclone_reports_version "${latest}"
check "the three completion files equal what the installed rclone generates" completions_match

copy_between_local_directories() {
  copy_dir="$(mktemp -d)" || return 1
  mkdir "${copy_dir}/source" "${copy_dir}/destination"
  printf 'rclone feature test\n' >"${copy_dir}/source/file.txt"
  isolated_rclone copy "${copy_dir}/source" "${copy_dir}/destination" || return 1
  same_content "${copy_dir}/source/file.txt" "${copy_dir}/destination/file.txt" || return 1
  rm -rf "${copy_dir}"
}
check "rclone copy between local directories without configuration exits 0 and copies the file" \
  copy_between_local_directories

# The Ubuntu base image loads bash-completion in interactive bash and has zsh with oh-my-zsh; the other images have
# neither, nor fish, and the install must not add them.
# shellcheck source=/dev/null
image_id="$(. /etc/os-release && printf '%s\n' "${ID}")"
if [ "${image_id}" = "ubuntu" ]; then
  bash_loads_completion() {
    bash_loads_output="$(bash -i -c \
      'if type _comp_load >/dev/null 2>&1; then _comp_load rclone; else __load_completion rclone; fi
       complete -p rclone' </dev/null 2>/dev/null)" || return 1
    printf '  %s\n' "${bash_loads_output}"
    case "${bash_loads_output}" in
      complete*' rclone') ;;
      *) return 1 ;;
    esac
  }
  check "the remote user's interactive bash loads a completion for rclone through bash-completion" \
    bash_loads_completion
  # shellcheck disable=SC2016 # $fpath is expanded by zsh, not by this script.
  check "the remote user's interactive zsh finds _rclone on its function path" \
    zsh -i -c 'for d in $fpath; do [[ -f $d/_rclone ]] && exit 0; done; exit 1' </dev/null
else
  no_shells_added() {
    for no_shells_path in /usr/share/bash-completion/bash_completion /etc/profile.d/bash_completion.sh; do
      if [ -e "${no_shells_path}" ]; then
        printf '  found %s\n' "${no_shells_path}"
        return 1
      fi
    done
    for no_shells_command in zsh fish; do
      if command -v "${no_shells_command}" >/dev/null 2>&1; then
        printf '  %s resolves to %s\n' "${no_shells_command}" "$(command -v "${no_shells_command}")"
        return 1
      fi
    done
  }
  check "the install added none of bash-completion, zsh, and fish" no_shells_added
fi

prerequisites_on_path() {
  for prerequisites_command in curl gpg unzip; do
    if ! command -v "${prerequisites_command}" >/dev/null 2>&1; then
      printf '  %s is not on PATH\n' "${prerequisites_command}"
      return 1
    fi
  done
}
check "curl, gpg, and unzip are on PATH after the install" prerequisites_on_path
check "fusermount3 is absent, since installMountDependencies is false" sh -c '! command -v fusermount3'
check "apt's package lists, dnf's cache, and apk's cache hold no file" package_caches_empty
check "no temporary directory or staged file of the install remains" no_install_leftovers

reportResults
